const inputData = $input.first()?.json ?? {};
const message = inputData.message || '';
const userId = inputData.user_id || 'unknown';
function extractDate(text) {
  const tomorrowMatch = text.match(/завтра/i);
  const todayMatch = text.match(/сегодня/i);
  const dateMatch = text.match(/(\d{1,2})\.(\d{1,2})\.(\d{2,4})/);
  if (tomorrowMatch) { const tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate() + 1); return tomorrow.toISOString().split('T')[0]; }
  if (todayMatch) { return new Date().toISOString().split('T')[0]; }
  if (dateMatch) { return dateMatch[3] + '-' + dateMatch[2].padStart(2, '0') + '-' + dateMatch[1].padStart(2, '0'); }
  return null;
}
function extractTime(text) {
  const timeMatch = text.match(/(\d{1,2}):(\d{2})/);
  if (timeMatch) { return timeMatch[1].padStart(2, '0') + ':' + timeMatch[2]; }
  return null;
}
function extractGuests(text) {
  const guestsMatch = text.match(/на (\d+) человек/);
  if (guestsMatch) { return parseInt(guestsMatch[1], 10); }
  const pairMatch = text.match(/на двоих/i);
  if (pairMatch) { return 2; }
  return null;
}
function extractLocation(text) {
  const centerMatch = text.match(/в центре|центр/i);
  const northMatch = text.match(/на севере|север/i);
  const southMatch = text.match(/на юге|юг/i);
  const eastMatch = text.match(/на востоке|восток/i);
  const westMatch = text.match(/на западе|запад/i);
  if (centerMatch) return 'Center';
  if (northMatch) return 'North';
  if (southMatch) return 'South';
  if (eastMatch) return 'East';
  if (westMatch) return 'West';
  return null;
}
function determineIntent(text) {
  const searchKeywords = /найди|поиск|подбери|вариант|место|ресторан|кафе/i;
  if (searchKeywords.test(text)) { return 'search_options'; }
  return 'unknown';
}
const date = extractDate(message);
const time = extractTime(message);
const guests = extractGuests(message);
const location = extractLocation(message);
const intent = determineIntent(message);
const sessionId = 'sess_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
return { user_id: userId, session_id: sessionId, message: message, intent: intent, extracted_data: { date, time, guests, location }, raw_input: inputData, timestamp: new Date().toISOString() };

const inputData = $input.first()?.json ?? {};
const extracted = inputData.extracted_data || {};
const requiredFields = ['date', 'time', 'guests', 'location'];
const missingFields = requiredFields.filter(field => !extracted[field]);
const isValid = missingFields.length === 0;
return { ...inputData, validation: { is_valid: isValid, missing_fields: missingFields, checked_at: new Date().toISOString() } };

const workerResponse = $input.first()?.json ?? {};
const sessionContext = $input.all()[1]?.json ?? {};
return { status: 'success', intent: sessionContext.intent || 'search_options', session_id: sessionContext.session_id, results: workerResponse.results || [], results_count: workerResponse.results_count || 0, search_params: workerResponse.search_params, timestamp: new Date().toISOString() };

const error = $input.first()?.json?.error ?? new Error('Orchestrator error');
const sessionData = $input.all()[0]?.json ?? {};
return { status: 'error', intent: sessionData.intent || 'unknown', session_id: sessionData.session_id || 'unknown', message: error.message || 'Worker execution failed', error_type: 'orchestrator_error', timestamp: new Date().toISOString() };

const sessionData = $input.first()?.json ?? {};
const responseStatus = sessionData.status || 'completed';
return { session_id: sessionData.session_id, new_status: responseStatus === 'error' ? 'error' : 'completed', updated_at: new Date().toISOString() };
